class Temp private (val deg: Int)
object Temp:
  def apply(d: Int): Temp = new Temp(math.max(d, -273))
  def fromF(f: Int): Temp = Temp((f - 32) * 5 / 9)
Temp(-500).deg // => -273
Temp.fromF(212).deg // => 100

def firstOr[A](xs: List[A], d: A): A = xs.headOption.getOrElse(d)
firstOr(List(1, 2), 0) // => 1
firstOr(List.empty[String], "none") // => none
class Box[A](val a: A):
  def map[B](f: A => B): Box[B] = Box(f(a))
Box(3).map(_ + 1).a // => 4
